    if run_tool "RUNTIME_HEALTH_PUBLISHER" "${UNIVERSAL_HEALTH_TIMEOUT_SECONDS:-60}" "$PYTHON_BIN" "$HEALTH_PUBLISHER"; then
        log "RUNTIME_HEALTH_PUBLISHER_STATE=READY"
    else
        log "RUNTIME_HEALTH_PUBLISHER_STATE=ERROR"
    fi
}

reconcile_once() {
    [ -f "$RECONCILER" ] || { log "WORKER_RUNTIME_RECONCILER_AVAILABLE=NO"; return 0; }
    if run_tool "WORKER_RUNTIME_RECONCILER" "${UNIVERSAL_RECONCILE_TIMEOUT_SECONDS:-90}" "$PYTHON_BIN" "$RECONCILER"; then
        log "WORKER_RUNTIME_RECONCILER_STATE=READY"
    else
        log "WORKER_RUNTIME_RECONCILER_STATE=ERROR"
    fi
}

