health_loop() {
    while [ "$RUNNING" -eq 1 ]; do
        if is_authorized; then publish_health_once; else log "HEALTH_STATE=DISABLED"; fi
        sleep "$HEALTH_SECONDS" || true
    done
}

reconcile_loop() {
    while [ "$RUNNING" -eq 1 ]; do
        if is_authorized; then reconcile_once; else log "RECONCILE_STATE=DISABLED"; fi
        sleep "$RECONCILE_SECONDS" || true
    done
}

